import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","link":"/life/english/new-concept/book-1/review-part-02"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第24–31课","link":"/life/english/new-concept/book-1/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","link":"/life/english/new-concept/book-1/review-part-02"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第24–31课","link":"/life/english/new-concept/book-1/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-03.md","filePath":"life/english/new-concept/book-1/review-part-03.md"}'),n={name:"life/english/new-concept/book-1/review-part-03.md"};function r(i,e,l,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第16–23课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第16–23课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第16–23课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第16–23课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-16-·-名词复数与复数-be" tabindex="-1">Lesson 16 · 名词复数与复数 be <a class="header-anchor" href="#lesson-16-·-名词复数与复数-be" aria-label="Permalink to &quot;Lesson 16 · 名词复数与复数 be {#lesson-16-·-名词复数与复数-be}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Are these your passports?</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>passport 的复数形式是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> passports</p><p><strong>解析：</strong> 按本课规则判断：多数可数名词复数加 s；以 s、sh、ch 等结尾常加 es。you 既可指一人也可指多人，be 都用 are。we 和 they 也用 are。these/those 指复数对象，不能与 is 或单数 passport 搭配。称呼多人时，your 本身不加 s；数量信息由后面的名词体现。</p></details><p><strong>表达迁移：</strong> 围绕“多人场景下核对身份和证件”写两至三句，再读给同伴听。至少使用一次名词复数与复数 be，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Are these your passports? These tourists are from Spain.</p><p>Are 前置，these 是复数主语，your passports 是复数名词表语；your 的形式不因多人多本护照而改变。 These tourists 是复数主语，are from Spain 表来源；these 与复数 tourists 配合，Spain 是国家专名。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-016">回看本课</a></p><h2 id="lesson-17-·-复数职业与-their" tabindex="-1">Lesson 17 · 复数职业与 their <a class="header-anchor" href="#lesson-17-·-复数职业与-their" aria-label="Permalink to &quot;Lesson 17 · 复数职业与 their {#lesson-17-·-复数职业与-their}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Maya and Leo are office assistants.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>填 be：Maya and Leo ___ assistants.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：their 用于说明“他们/她们/它们的”，后面既能接单数也能接复数名词，取决于被拥有的东西。多人职业可用 They are engineers；复数泛指职业不加 a/an。What are their jobs? 中 jobs 与 are 对应。介绍名单时用人名说明对象，再用 they 避免机械重复。</p></details><p><strong>表达迁移：</strong> 围绕“向团队成员作介绍”写两至三句，再读给同伴听。至少使用一次复数职业与 their，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Maya and Leo are office assistants. Their office is on the first floor.</p><p>Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。 Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-017">回看本课</a></p><h2 id="lesson-18-·-复数职业与-their" tabindex="-1">Lesson 18 · 复数职业与 their <a class="header-anchor" href="#lesson-18-·-复数职业与-their" aria-label="Permalink to &quot;Lesson 18 · 复数职业与 their {#lesson-18-·-复数职业与-their}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Their office is on the first floor.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>选择 their/they&#39;re：___ office is small.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Their</p><p><strong>解析：</strong> 按本课规则判断：their 用于说明“他们/她们/它们的”，后面既能接单数也能接复数名词，取决于被拥有的东西。多人职业可用 They are engineers；复数泛指职业不加 a/an。What are their jobs? 中 jobs 与 are 对应。介绍名单时用人名说明对象，再用 they 避免机械重复。</p></details><p><strong>表达迁移：</strong> 围绕“向团队成员作介绍”写两至三句，再读给同伴听。至少使用一次复数职业与 their，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Their office is on the first floor. Maya and Leo are office assistants.</p><p>Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。 Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-018">回看本课</a></p><h2 id="lesson-19-·-主格和宾格" tabindex="-1">Lesson 19 · 主格和宾格 <a class="header-anchor" href="#lesson-19-·-主格和宾格" aria-label="Permalink to &quot;Lesson 19 · 主格和宾格 {#lesson-19-·-主格和宾格}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The runners are tired and hungry.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填 be：The runners ___ tired.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p></details><p><strong>表达迁移：</strong> 围绕“描述多人状态并用代词指代”写两至三句，再读给同伴听。至少使用一次主格和宾格，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The runners are tired and hungry. Look at them near the gate.</p><p>The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。 Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-019">回看本课</a></p><h2 id="lesson-20-·-主格和宾格" tabindex="-1">Lesson 20 · 主格和宾格 <a class="header-anchor" href="#lesson-20-·-主格和宾格" aria-label="Permalink to &quot;Lesson 20 · 主格和宾格 {#lesson-20-·-主格和宾格}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Look at them near the gate.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>选择 they/them：Look at ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> them</p><p><strong>解析：</strong> 按本课规则判断：主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p></details><p><strong>表达迁移：</strong> 围绕“描述多人状态并用代词指代”写两至三句，再读给同伴听。至少使用一次主格和宾格，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Look at them near the gate. The runners are tired and hungry.</p><p>Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。 The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-020">回看本课</a></p><h2 id="lesson-21-·-which-与-one-的替代" tabindex="-1">Lesson 21 · which 与 one 的替代 <a class="header-anchor" href="#lesson-21-·-which-与-one-的替代" aria-label="Permalink to &quot;Lesson 21 · which 与 one 的替代 {#lesson-21-·-which-与-one-的替代}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Please give me the empty box.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>选择 I/me：Please give ___ the box.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> me</p><p><strong>解析：</strong> 按本课规则判断：which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p></details><p><strong>表达迁移：</strong> 围绕“从多个单数物品中指定一个”写两至三句，再读给同伴听。至少使用一次which 与 one 的替代，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please give me the empty box. Which notebook do you want: the red one or the blue one?</p><p>Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。 Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">回看本课</a></p><h2 id="lesson-22-·-which-与-one-的替代" tabindex="-1">Lesson 22 · which 与 one 的替代 <a class="header-anchor" href="#lesson-22-·-which-与-one-的替代" aria-label="Permalink to &quot;Lesson 22 · which 与 one 的替代 {#lesson-22-·-which-与-one-的替代}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Which notebook do you want: the red one or the blue one?</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>补替代词：the red notebook → the red ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> one</p><p><strong>解析：</strong> 按本课规则判断：which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p></details><p><strong>表达迁移：</strong> 围绕“从多个单数物品中指定一个”写两至三句，再读给同伴听。至少使用一次which 与 one 的替代，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Which notebook do you want: the red one or the blue one? Please give me the empty box.</p><p>Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。 Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-022">回看本课</a></p><h2 id="lesson-23-·-ones-与复数选择" tabindex="-1">Lesson 23 · ones 与复数选择 <a class="header-anchor" href="#lesson-23-·-ones-与复数选择" aria-label="Permalink to &quot;Lesson 23 · ones 与复数选择 {#lesson-23-·-ones-与复数选择}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Please give us the clean plates.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>选择 we/us：Give ___ some plates.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> us</p><p><strong>解析：</strong> 按本课规则判断：ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p></details><p><strong>表达迁移：</strong> 围绕“从多件物品中挑选一组”写两至三句，再读给同伴听。至少使用一次ones 与复数选择，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please give us the clean plates. I want the small ones beside the sink.</p><p>Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。 I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-023">回看本课</a></p>',68)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
